INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('1', 'Jasa Pembuatan Website & Web Application', 'pembuatan-website-aplikasi-web', 'fas fa-globe', 'RECOMMENDED', 'Pengembangan website responsif, company profile, toko online (e-commerce), dan sistem informasi bisnis berbasis Laravel & React.', 'Mulai Dari', 'Rp 2.500.000', '2500000', '/ project', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=800&q=80', 'Kami menyediakan jasa pembuatan website profesional yang dirancang khusus untuk meningkatkan kredibilitas dan penjualan bisnis Anda. Menggunakan teknologi modern terkini dengan desain elegan, SEO-friendly, dan akses super cepat.', '[\"Desain Responsive & Modern\",\"Optimasi SEO & Kecepatan Tinggi\",\"Integrasi Payment Gateway\",\"Gratis Domain & Hosting 1 Tahun\"]', '[\"Free Source Code\",\"Gratis Revisi Desain\",\"Garansi & Support 6 Bulan\",\"Panduan Penggunaan Admin Panel\"]', '[\"Desain Kustom Eksklusif (Non-Template)\",\"Content Management System (CMS) Mudah Digunakan\",\"Integrasi WhatsApp & Live Chat Widget\",\"Keamanan SSL Certificate Terpasang\",\"Analitik Pengunjung (Google Analytics)\"]', 'Halo Elcoding, saya ingin berkonsultasi mengenai Jasa Pembuatan Website & Web Application.', '2026-09-09 07:04:38', '2026-09-09 07:04:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('2', 'Pengembangan Aplikasi Mobile (Android & iOS)', 'pengembangan-aplikasi-mobile', 'fas fa-mobile-alt', 'TERLARIS', 'Aplikasi mobile cross-platform performa tinggi menggunakan Flutter & React Native dengan desain UI/UX interaktif.', 'Mulai Dari', 'Rp 4.500.000', '4500000', '/ project', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?auto=format&fit=crop&w=800&q=80', 'Wujudkan ide aplikasi mobile impian Anda untuk Android dan iOS dalam satu codebase efisien. Dilengkapi backend API terstruktur, push notification, serta performa native yang mulus.', '[\"Support Android & iOS\",\"UI\\/UX Interactive & Smooth\",\"Push Notification Realtime\",\"Integrasi API & Cloud DB\"]', '[\"Bantuan Publish ke Google PlayStore & AppStore\",\"Dokumentasi REST API Complete\",\"Free Maintenance 3 Bulan\"]', '[\"Multi-language Support\",\"Fitur Lokasi \\/ GPS Mapping\",\"Sistem Keamanan Auth JWT & Biometric Login\",\"Optimasi Ukuran App & Baterai\"]', 'Halo Elcoding, saya berminat membuat Aplikasi Mobile untuk bisnis saya.', '2026-09-09 07:04:38', '2026-09-09 07:04:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('3', 'Jasa UI/UX Design & Prototyping', 'jasa-ui-ux-design-prototyping', 'fas fa-paint-brush', 'PROMO', 'Perancangan antarmuka pengguna (UI) dan pengalaman pengguna (UX) berbasis penelitian pengguna dan Design System scalable.', 'Mulai Dari', 'Rp 1.200.000', '1200000', '/ project', 'https://images.unsplash.com/photo-1581291518633-83b4ebd1d83e?auto=format&fit=crop&w=800&q=80', 'Layanan pembuatan kraf wireframe, prototype interaktif Figma, serta Design System standar industri untuk mempermudah proses koding tim developer Anda.', '[\"Figma Source File (.fig)\",\"Design System & Component Library\",\"Clickable Interactive Prototype\",\"User Research & Wireframing\"]', '[\"Export Aset SVG\\/PNG\\/JPG\",\"Design Handoff ke Developer\",\"Revisi Sesuai Feedback\"]', '[\"UX Audit & Usability Testing\",\"Responsive Layouts (Desktop & Mobile)\",\"Iconography & Design Palette Custom\"]', 'Halo Elcoding, saya butuh layanan Jasa UI/UX Design untuk aplikasi saya.', '2026-09-09 07:04:38', '2026-09-09 07:04:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('4', 'Private Corporate IT Training', 'private-corporate-it-training', 'fas fa-users-cog', 'SPECIAL', 'Pelatihan teknologi dan pemrograman khusus perusahaan & instansi dengan kurikulum kustom disesuaikan kebutuhan industri Anda.', 'Mulai Dari', 'Rp 3.500.000', '3500000', '/ batch', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=800&q=80', 'Tingkatkan kompetensi digital tim internal perusahaan Anda dalam topik Fullstack Web Development, DevOps, Cloud Infrastructure, atau AI/Data Science bersama instruktur praktisi berpengalaman.', '[\"Kurikulum Custom Sesuai Project Tim\",\"Instruktur Expert Praktisi Industri\",\"Modul & Sertifikat Pelatihan\",\"Konsultasi Studi Kasus Real\"]', '[\"Materi Presentasi & Source Code\",\"Sertifikat Kelulusan Peserta\",\"Evaluasi Hasil Pembelajaran\"]', '[\"Pilihan Metode Onsite atau Online Live Class\",\"Recording Sesi Pelatihan Harian\",\"Group Support Telegram \\/ Slack Dedikasi\"]', 'Halo Elcoding, kami ingin mengadakan Corporate IT Training untuk perusahaan kami.', '2026-09-09 07:04:38', '2026-09-09 07:04:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('5', 'Cloud Server, DevOps & Maintenance', 'cloud-devops-maintenance-server', 'fas fa-server', 'POPULER', 'Konfigurasi cloud server (AWS, GCP, VPS), automasi CI/CD pipeline, monitoring keamanan, dan perawatan server berkala.', 'Mulai Dari', 'Rp 990.000', '990000', '/ bulan', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=800&q=80', 'Jaga kestabilan dan keamanan aplikasi bisnis Anda tanpa perlu khawatir server down. Layanan DevOps dan managed server profesional untuk skalabilitas bisnis tinggi.', '[\"Setup Cloud VPS \\/ Server AWS GCP\",\"Automasi Deployment CI\\/CD\",\"Backup Database Otomatis Harian\",\"Monitoring Server 24\\/7 Uptime\"]', '[\"Firewall & Hardening Security\",\"SSL Certificate Management\",\"Laporan Performa Bulanan\"]', '[\"Docker & Kubernetes Containerization\",\"Load Balancer Configuration\",\"Penanganan Insiden Darurat (SLA Fast Response)\"]', 'Halo Elcoding, saya butuh layanan Cloud Server & DevOps Maintenance.', '2026-09-09 07:04:38', '2026-09-09 07:04:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('6', 'Audit Keamanan Website & PenTest', 'audit-keamanan-website-penetration-testing', 'fas fa-shield-alt', 'BARU', 'Pengujian penetrasi (Penetration Testing) dan analisis celah keamanan website serta server aplikasi dari potensi peretasan.', 'Mulai Dari', 'Rp 1.950.000', '1950000', '/ audit', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=800&q=80', 'Lindungi data sensitif pelanggan dan reputasi bisnis Anda dari ancaman cyber crime, SQL injection, XSS, dan kebocoran data dengan pengujian keamanan standar OWASP.', '[\"Vulnerability Assessment OWASP Top 10\",\"Penetration Testing Blackbox & Graybox\",\"Laporan Rekomendasi Perbaikan\",\"Re-Testing Setelah Fix Celah\"]', '[\"Dokumen Executive Summary Audit\",\"Panduan Remediasi Teknis\",\"Sertifikat Audit Keamanan\"]', '[\"Pemeriksaan Security Header & Network Port\",\"Analisis Kerentanan API Endpoint\",\"Konsultasi Tim Security Specialist\"]', 'Halo Elcoding, saya ingin berkonsultasi untuk Audit Keamanan Website / PenTest.', '2026-09-09 07:04:38', '2026-09-09 07:04:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('7', 'Website Sekolah', 'website-sekolah', 'fas fa-globe', 'Website', 'Pembuatan website sekolah instan untuk TK, SD, SMP, SMA, SMK, SLB, Madrasah, Ponpes, Yayasan dan Lembaga Pendidikan lainnya. Website modern, responsif, dan mudah dikelola.', 'Mulai dari', 'Rp 375.000', NULL, '/ tahun', '', '<p>Di era digital saat ini, memiliki website resmi sekolah sangatlah penting untuk menunjang akreditasi, transparansi informasi, dan media komunikasi yang efektif antara pihak sekolah, siswa, dan masyarakat.</p><p>Elcoding hadir memberikan solusi pembuatan website sekolah instan yang siap pakai, sudah termasuk gratis pendaftaran domain resmi <strong>.sch.id</strong>, hosting yang cepat dan stabil, serta kontrol panel yang mudah digunakan oleh tenaga pendidik atau tata usaha sekolah tanpa perlu keahlian pemrograman (coding) sama sekali.</p>', '[{\"icon\":\"fas fa-check-circle\",\"title\":\"Desain Modern & Responsif\",\"desc\":\"Tampilan elegan, profesional, dan menyesuaikan otomatis dengan layar perangkat pengunjung (HP, Tablet, maupun PC).\"},{\"icon\":\"fas fa-check-circle\",\"title\":\"Terintegrasi Fitur Akademik\",\"desc\":\"Dilengkapi dengan fitur standar sekolah seperti Berita, Pengumuman, Agenda, Galeri Kegiatan, dan Profil Sekolah.\"},{\"icon\":\"fas fa-check-circle\",\"title\":\"Panel Admin Mudah Digunakan\",\"desc\":\"Dashboard berbahasa Indonesia yang intuitif, dirancang agar mudah digunakan untuk menambah atau mengedit artikel secara mandiri.\"},{\"icon\":\"fas fa-check-circle\",\"title\":\"Gratis Domain .sch.id & Hosting\",\"desc\":\"Terima beres! Paket sudah mencakup biaya pendaftaran nama domain .sch.id dan sewa hosting untuk 1 tahun pertama.\"}]', '[\"Website Instan Siap Pakai\",\"Gratis Domain .sch.id (1 thn)\",\"Gratis Hosting & SSL (1 thn)\",\"Fitur Lengkap Informasi Sekolah\",\"Video Panduan & Support Teknis\"]', '[{\"icon\":\"fas fa-bolt\",\"color_class\":\"icon-blue\",\"title\":\"Proses Instan 60 Menit\",\"desc\":\"Website sekolah aktif dan online hanya dalam 60 menit setelah pembayaran dikonfirmasi.\"},{\"icon\":\"fas fa-globe\",\"color_class\":\"icon-cyan\",\"title\":\"Domain .sch.id\",\"desc\":\"Dapatkan domain resmi .sch.id yang menunjukkan identitas profesional sekolah Anda.\"},{\"icon\":\"fas fa-columns\",\"color_class\":\"icon-purple\",\"title\":\"Kontrol Panel Website\",\"desc\":\"Kelola konten, halaman, dan menu website secara mandiri tanpa keahlian coding.\"},{\"icon\":\"fas fa-database\",\"color_class\":\"icon-blue\",\"title\":\"Kontrol Panel Hosting\",\"desc\":\"Akses penuh ke cPanel untuk mengelola file, database, dan email sekolah.\"},{\"icon\":\"fas fa-shield-alt\",\"color_class\":\"icon-green\",\"title\":\"Gratis HTTPS \\/ SSL\",\"desc\":\"Sertifikat SSL otomatis aktif untuk keamanan data dan kepercayaan pengunjung.\"},{\"icon\":\"fas fa-cloud-upload-alt\",\"color_class\":\"icon-cyan\",\"title\":\"Backup Harian\",\"desc\":\"Data website di-backup setiap hari sehingga aman dari kehilangan atau kerusakan.\"},{\"icon\":\"far fa-building\",\"color_class\":\"icon-blue\",\"title\":\"Dikelola Sekolah Sendiri\",\"desc\":\"Admin sekolah bisa memperbarui berita, agenda, dan konten tanpa bantuan pihak lain.\"},{\"icon\":\"fas fa-user-shield\",\"color_class\":\"icon-green\",\"title\":\"Garansi Keamanan Website\",\"desc\":\"Kami menjamin keamanan website dari serangan malware dan uptime server yang stabil.\"},{\"icon\":\"fas fa-play\",\"color_class\":\"icon-purple\",\"title\":\"Video Tutorial Pengelolaan\",\"desc\":\"Tersedia video panduan lengkap di channel YouTube websekolah.official untuk membantu Anda.\"},{\"icon\":\"fas fa-video\",\"color_class\":\"icon-blue\",\"title\":\"Konsultasi Google Meet\",\"desc\":\"Tim kami siap mendampingi via Google Meet untuk pelatihan dan konsultasi.\"},{\"icon\":\"fab fa-whatsapp\",\"color_class\":\"icon-green\",\"title\":\"Support WhatsApp & Group\",\"desc\":\"Chat langsung dengan tim teknis kami melalui WhatsApp kapanpun dibutuhkan.\"},{\"icon\":\"fas fa-sync-alt\",\"color_class\":\"icon-purple\",\"title\":\"Update Fitur Berkala\",\"desc\":\"Website sekolah Anda akan selalu mendapatkan fitur-fitur terbaru secara otomatis.\"}]', 'Halo Admin Elcoding, saya ingin pesan layanan Website Sekolah.', '2026-09-09 08:56:38', '2026-09-09 08:56:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('8', 'Hosting eRapor SMK', 'hosting-erapor-smk', 'fas fa-server', 'Hosting', 'Hosting khusus untuk eRapor SMK yang aplikasinya disediakan oleh Direktorat SMK melalui situs erapor-smk.net. Dukungan penuh dari tim kami.', 'Harga', 'Rp 210.000', NULL, '/ tahun', NULL, '<p>Kini Anda tidak perlu lagi repot mengatur server lokal di sekolah yang harus selalu menyala 24 jam. Elcoding menyediakan layanan hosting khusus yang dirancang optimal untuk aplikasi <strong>eRapor SMK</strong>.</p><p>Aplikasi eRapor SMK Anda dapat diakses dari mana saja dan kapan saja secara online oleh para guru dan wali kelas tanpa terkendala infrastruktur jaringan lokal.</p>', '[{\"icon\":\"fas fa-rocket\",\"title\":\"Performa Tinggi\",\"desc\":\"Server dioptimalkan secara khusus untuk menjalankan aplikasi eRapor SMK dengan cepat tanpa lag.\"},{\"icon\":\"fas fa-shield-alt\",\"title\":\"Aman & Backup Terjadwal\",\"desc\":\"Data eRapor aman dengan sistem keamanan ketat dan backup otomatis berkala.\"},{\"icon\":\"fas fa-headset\",\"title\":\"Bantuan Setup Awal\",\"desc\":\"Tim kami akan membantu proses instalasi dan pemindahan database eRapor dari lokal ke server.\"},{\"icon\":\"fas fa-globe\",\"title\":\"Akses Darimana Saja\",\"desc\":\"Guru dapat mengisi nilai rapor dari rumah atau dimanapun menggunakan koneksi internet biasa.\"}]', '[\"Spesifikasi Server Optimal eRapor\",\"Gratis Instalasi \\/ Migrasi Database\",\"Subdomain (contoh: erapor.namasekolah.sch.id)\",\"SSL Certificate (HTTPS)\",\"Bantuan Teknis Prioritas\"]', '[]', 'Halo Admin Elcoding, saya ingin pesan layanan Hosting eRapor SMK.', '2026-09-09 08:56:38', '2026-09-09 08:56:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('9', 'Hosting RDM', 'hosting-rdm', 'fas fa-server', 'Hosting', 'Hosting khusus untuk Rapor Digital Madrasah (RDM) yang aplikasinya disediakan oleh Kementerian Agama melalui rdm.kemenag.go.id. Cepat, stabil, dan terpercaya.', 'Harga', 'Rp 150.000', NULL, '/ tahun', NULL, '<p>Rapor Digital Madrasah (RDM) merupakan aplikasi wajib dari Kemenag. Namun instalasi di server lokal sekolah seringkali merepotkan karena keterbatasan spesifikasi PC dan keharusan IP Public.</p><p>Kami menawarkan solusi <strong>Hosting Khusus RDM</strong> yang siap pakai, aman, dan sangat ringan, sehingga guru-guru di Madrasah Anda dapat mengerjakan RDM darimana saja.</p>', '[{\"icon\":\"fas fa-tachometer-alt\",\"title\":\"Lancar & Ringan\",\"desc\":\"Disesuaikan dengan spesifikasi yang dibutuhkan RDM agar dapat diakses banyak guru secara bersamaan.\"},{\"icon\":\"fas fa-tools\",\"title\":\"Bebas Ribet Instalasi\",\"desc\":\"Anda terima beres, tidak perlu memikirkan XAMPP, VDI, atau konfigurasi jaringan.\"},{\"icon\":\"fas fa-cloud-download-alt\",\"title\":\"Backup Rutin\",\"desc\":\"Nilai siswa sangat berharga, karenanya kami rutin membackup database RDM sekolah Anda.\"},{\"icon\":\"fas fa-check\",\"title\":\"Selalu Update\",\"desc\":\"Jika ada pembaruan versi dari pusat, tim kami siap membantu melakukan update versi RDM.\"}]', '[\"Server Khusus RDM\",\"Gratis Instalasi RDM\",\"Subdomain (contoh: rdm.namamadrasah.sch.id)\",\"Gratis SSL (HTTPS)\",\"Support Bantuan Kendala\"]', '[]', 'Halo Admin Elcoding, saya ingin pesan layanan Hosting RDM.', '2026-09-09 08:56:38', '2026-09-09 08:56:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('10', 'Cloud Server', 'cloud-server', 'fas fa-database', 'Cloud', 'Cloud server untuk aplikasi eRapor & Dapodik baik untuk SD/SMP/SMA/SMK dengan sistem operasi Windows Server dan akses dengan domain sendiri.', 'Mulai dari', 'Rp 375.000', NULL, '/ 3 bulan', NULL, '<p>Bagi sekolah yang memiliki aplikasi berat atau spesifik yang mengharuskan penggunaan sistem operasi Windows Server, layanan Cloud Server (VPS Windows) kami adalah jawabannya.</p><p>Biasa digunakan untuk menghosting Dapodik, eRapor versi khusus, aplikasi CBT, hingga sistem informasi manajemen mandiri milik sekolah dengan kebebasan penuh akses Administrator (RDP).</p>', '[{\"icon\":\"fab fa-windows\",\"title\":\"Windows Server\",\"desc\":\"Sudah dilengkapi dengan sistem operasi Windows Server siap pakai.\"},{\"icon\":\"fas fa-desktop\",\"title\":\"Akses Remote Desktop (RDP)\",\"desc\":\"Anda bisa meremote server sama seperti menjalankan PC biasa di sekolah Anda.\"},{\"icon\":\"fas fa-network-wired\",\"title\":\"Dedicated IP\",\"desc\":\"Mendapatkan IP Public Dedicated untuk kestabilan akses dari luar jaringan.\"},{\"icon\":\"fas fa-bolt\",\"title\":\"Penyimpanan SSD NVMe\",\"desc\":\"Kecepatan read\\/write data sangat tinggi untuk menangani database besar.\"}]', '[\"RAM 4GB & 2 vCPU\",\"SSD NVMe 50GB\",\"Windows Server 2012\\/2016\\/2019\",\"1 Dedicated IP Public\",\"Full Akses Administrator\"]', '[]', 'Halo Admin Elcoding, saya butuh layanan Cloud Server untuk sekolah saya.', '2026-09-09 08:56:38', '2026-09-09 08:56:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('11', 'Sitesch.id', 'sitesch-id', 'fab fa-wordpress', 'Template', 'Template WordPress Sitesch.ID siap pakai untuk website sekolah modern, responsif, dan berfitur lengkap. Beli sekali, aktif selamanya tanpa biaya berulang.', 'Harga', 'Rp 395.000', NULL, '/ sekali beli', NULL, '<p>Sitesch.ID merupakan template WordPress eksklusif yang dirancang khusus untuk kebutuhan Website Sekolah di Indonesia.</p><p>Hanya dengan sekali bayar, Anda mendapatkan lisensi penggunaan selamanya, lengkap dengan fitur PSB (Penerimaan Siswa Baru), Galeri, Berita, Pengumuman Kelulusan, dan berbagai fitur akademik lainnya.</p>', '[{\"icon\":\"fas fa-money-bill-wave\",\"title\":\"Beli Sekali, Pakai Selamanya\",\"desc\":\"Tidak ada biaya langganan bulanan atau tahunan untuk template ini.\"},{\"icon\":\"fas fa-puzzle-piece\",\"title\":\"Fitur Khusus Sekolah\",\"desc\":\"Sudah terpasang modul Guru, Siswa, Fasilitas, hingga formulir pendaftaran murid baru.\"},{\"icon\":\"fas fa-mobile-alt\",\"title\":\"Sangat Responsif\",\"desc\":\"Desain akan selalu terlihat sempurna meski diakses melalui layar smartphone terkecil sekalipun.\"},{\"icon\":\"fas fa-cogs\",\"title\":\"Mudah Dikustomisasi\",\"desc\":\"Anda dapat mengubah warna, logo, dan tata letak dengan mudah melalui panel opsi tema.\"}]', '[\"1 Lisensi Domain\",\"File Template Asli (Bersih dari Malware)\",\"Dokumentasi & Video Panduan\",\"Gratis Update Minor\",\"Support Bantuan Instalasi\"]', '[]', 'Halo Admin Elcoding, saya tertarik membeli template Sitesch.id.', '2026-09-09 08:56:38', '2026-09-09 08:56:38');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('12', 'E-Library Sekolah', 'e-library-sekolah', 'fas fa-book', 'Perpustakaan Digital', 'Perpustakaan digital untuk sekolah — katalog buku online, peminjaman mandiri, dan baca e-book langsung dari browser tanpa perlu instalasi.', 'Harga', 'Rp 425.000', NULL, '/ tahun', NULL, '<p>Ubah perpustakaan fisik sekolah Anda menjadi perpustakaan digital modern dengan E-Library Sekolah.</p><p>Aplikasi ini memungkinkan siswa untuk mencari katalog buku, melakukan peminjaman secara digital, atau bahkan membaca E-Book PDF langsung dari perangkat mereka, sehingga menumbuhkan minat baca siswa di era digital.</p>', '[{\"icon\":\"fas fa-search\",\"title\":\"Katalog Buku Online\",\"desc\":\"Siswa dapat mencari buku berdasarkan judul, pengarang, atau kategori dengan sangat mudah.\"},{\"icon\":\"fas fa-barcode\",\"title\":\"Manajemen Peminjaman\",\"desc\":\"Dilengkapi fitur peminjaman, pengembalian, dan denda keterlambatan.\"},{\"icon\":\"fas fa-file-pdf\",\"title\":\"Baca E-Book Langsung\",\"desc\":\"Siswa bisa membaca materi berformat PDF\\/E-Book langsung di dalam aplikasi tanpa mendownloadnya.\"},{\"icon\":\"fas fa-chart-pie\",\"title\":\"Laporan Statistik\",\"desc\":\"Pustakawan bisa mencetak laporan jumlah peminjam, buku paling populer, dan laporan stok buku.\"}]', '[\"Aplikasi E-Library Lengkap\",\"Gratis Hosting Aplikasi 1 Tahun\",\"Subdomain Perpustakaan\",\"Panduan Penggunaan\",\"Bantuan Teknis\"]', '[]', 'Halo Admin Elcoding, saya ingin bertanya tentang layanan E-Library Sekolah.', '2026-09-09 08:56:38', '2026-09-09 08:56:38');
