INSERT INTO `mou_sections` (`id`, `mou_id`, `title`, `type`, `content`, `images`, `order`, `created_at`, `updated_at`) VALUES ('1', '4', 'BAGIAN 1: KERJASAMA PENGEMBANGAN SINERGIS DENGAN LAZIZMU', 'block', '[{\"type\":\"text\",\"content\":\"<p><strong>Kerjasama Pengembangan Sinergis dengan LazizMU<\\/strong><\\/p><p>Dokumentasi penandatanganan dan pembahasan kerjasama strategis antara Elcoding Academy dan LazizMU untuk pengembangan ekosistem digital terpadu.<\\/p>\"},{\"type\":\"text\",\"content\":\"<p><img src=\\\"\\/gambar\\/portofolio\\/kerjasama-lazizmu.webp\\\" alt=\\\"Kerjasama Pengembangan Sinergis dengan LazizMU\\\" style=\\\"max-width: 100%; height: auto; border-radius: 8px;\\\" \\/><\\/p>\"}]', NULL, '0', '2026-09-02 04:52:44', '2026-09-02 04:52:44');
